/** Words for one event, English first: its catalogue label's lookup key and the two lists. */
export type EventTerms = { en: readonly string[]; bg: readonly string[] }

const split = (text: string) => text.split("|").map(part => part.trim()).filter(Boolean)

const TERMS = new Map<string, EventTerms>()
for (const [label, en, bg] of ENTRIES) {
  const terms: EventTerms = { en: split(en), bg: split(bg) }
  TERMS.set(label, terms)
  // The quick complications are saved and shown under the complications list's name ("Drug error" reads "Medication error").
  const canonical = canonicalComplicationLabel(label)
  if (canonical !== label) TERMS.set(canonical, terms)
}

/** Every label that has words, for checking coverage. */
export const EVENT_SYNONYM_LABELS: readonly string[] = Object.freeze(ENTRIES.map(entry => entry[0]))

/** The words for an event, or none, by its catalogue label or its complications-list name. */
export const eventTerms = (label: string): EventTerms => TERMS.get(label) ?? { en: [], bg: [] }

/** Lower case, accents and punctuation removed, so "Hypoxaemia", "hypoxaemia" and "hypoxaemia." read alike. */
export function foldSearchText(text: string): string {
  return text.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/[^\p{L}\p{N}]+/gu, " ").trim()
}

/**
 * How well a search matches an event, or null when it does not, best first: 0 for a name or word that is exactly what was
 * typed, 1 for one that starts with it, 2 for one with a word that starts with it, 3 for one that contains it, 4 when every
 * typed word is found somewhere in the event's names and words. The names are
 * the catalogue label, the label as shown, and the event's words in both languages.
 */
export function eventSearchScore(query: string, label: string, shown: readonly string[] = []): number | null {
  const q = foldSearchText(query)
  if (!q) return null
  const terms = eventTerms(label)
  const names = [label, ...shown, ...terms.en, ...terms.bg].map(foldSearchText).filter(Boolean)
  if (names.includes(q)) return 0
  if (names.some(name => name.startsWith(q))) return 1
  if (!q.includes(" ") && names.some(name => name.split(" ").some(word => word.startsWith(q)))) return 2
  if (names.some(name => name.includes(q))) return 3
  const words = q.split(" ")
  const haystack = names.join(" ")
  return words.length > 1 && words.every(word => haystack.includes(word)) ? 4 : null
}
